<?php
 namespace App; use App\Model_ as Model; use Illuminate\Support\Facades\Cache; class Pay extends Model { protected $guarded = []; public static function gets() { return Cache::remember('model.pays', 10 * 60, function () { return self::query()->get(); }); } public static function flushCache() { Cache::forget('model.pays'); } protected static function boot() { parent::boot(); static::updated(function () { self::flushCache(); }); static::created(function () { self::flushCache(); }); static::deleted(function () { self::flushCache(); }); } } 